t.script:
(function(){
  var s = document.getElementById('status');
  var r = document.getElementById('result');
  var sendBtn = document.getElementById('send');
  var checkBtn = document.getElementById('check');
  sendBtn && sendBtn.addEventListener('click', function(){
    var v = document.getElementById('msg').value || '';
    fetch('/wuchang/ambassador/message', {
      method: 'POST',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify({message: v})
    }).then(function(x){return x.json()}).then(function(j){
      r.textContent = '已送出：' + (j.ok ? '成功' : '失敗');
    }).catch(function(){ r.textContent = '送出失敗'; });
  });
  checkBtn && checkBtn.addEventListener('click', function(){
    fetch('/wuchang/status', {method:'POST',headers:{'Content-Type':'application/json'}}).then(function(x){return x.json()}).then(function(j){
      s.textContent = JSON.stringify(j, null, 2);
    }).catch(function(){ s.textContent = '檢查失敗'; });
  });
})();
